CREATE TABLE IF NOT EXISTS shop_statement_issue(id BIGINT PRIMARY KEY AUTO_INCREMENT,company_id BIGINT NOT NULL,from_date DATE NOT NULL,to_date DATE NOT NULL,event_key VARCHAR(100) NOT NULL,note VARCHAR(300) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',resolution VARCHAR(300) NULL,operator_id BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY statement_issue(company_id,from_date,to_date,event_key));
CREATE TABLE IF NOT EXISTS shop_statement_confirmation(id BIGINT PRIMARY KEY AUTO_INCREMENT,company_id BIGINT NOT NULL,from_date DATE NOT NULL,to_date DATE NOT NULL,snapshot_hash VARCHAR(64) NOT NULL,snapshot_json MEDIUMTEXT NOT NULL,confirmed_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY statement_snapshot(company_id,from_date,to_date,snapshot_hash));
